CREATE FUNCTION agri.strategy_label_episode_checksum(p_label_episode_id uuid) RETURNS character varying
    LANGUAGE sql STABLE
    SET "TimeZone" TO 'UTC'
    SET "DateStyle" TO 'ISO, MDY'
    SET "IntervalStyle" TO 'postgres'
    SET extra_float_digits TO '1'
    AS $$
        SELECT encode(
            digest(
                concat_ws(
                    '|',
                    'strategy_label_episode_v1',
                    episode.episode_key,
                    episode.label_release_id::text,
                    episode.analysis_subject_id::text,
                    coalesce(episode.strategy_id::text, ''),
                    episode.arm_kind,
                    episode.cohort_key,
                    episode.assigned_at::text,
                    episode.intervention_start::text,
                    episode.intervention_end::text,
                    episode.baseline_start::text,
                    episode.baseline_end::text,
                    episode.outcome_start::text,
                    episode.outcome_end::text,
                    episode.baseline_evidence_input_id::text,
                    baseline.evidence_checksum,
                    episode.outcome_evidence_input_id::text,
                    observed.evidence_checksum,
                    episode.target_value::text,
                    episode.target_unit,
                    episode.assignment_mechanism,
                    coalesce(episode.known_assignment_probability::text, ''),
                    episode.spatial_block_key,
                    episode.covariate_snapshot::text,
                    episode.covariate_checksum,
                    episode.covariates_available_at::text,
                    episode.data_available_at::text,
                    label.strategy_taxonomy_checksum,
                    label.feature_schema_checksum,
                    label.extraction_plan_checksum,
                    label.extraction_code_checksum,
                    outcome.definition_checksum
                ),
                'sha256'
            ),
            'hex'
        )::varchar
        FROM agri.strategy_label_episode AS episode
        INNER JOIN agri.strategy_label_release AS label
            ON label.id = episode.label_release_id
        INNER JOIN agri.strategy_outcome_definition AS outcome
            ON outcome.id = label.outcome_definition_id
        INNER JOIN agri.intervention_evidence_input AS baseline
            ON baseline.id = episode.baseline_evidence_input_id
        INNER JOIN agri.intervention_evidence_input AS observed
            ON observed.id = episode.outcome_evidence_input_id
        WHERE episode.id = p_label_episode_id
    $$;
